-- Testify AI production foundation (PostgreSQL 15 / Supabase)
create extension if not exists pgcrypto;
create extension if not exists vector;
create type public.app_role as enum ('student','parent','educator','reviewer','admin');
create type public.content_status as enum ('draft','generated','validated','duplicate_check','subject_review','editorial_review','approved','published','flagged','retired');
create type public.question_type as enum ('multiple_choice','multiple_select','numeric','short_answer','free_response','proof','essay','coding','diagram','matching','ordering','passage_set','multi_part');
create type public.review_decision as enum ('pending','approved','rejected','changes_requested','copyright_flag');

create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, timezone text not null default 'UTC', daily_target smallint not null default 10 check(daily_target between 1 and 200), onboarding_complete boolean not null default false, accessibility jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.user_roles (user_id uuid references auth.users(id) on delete cascade, role app_role not null, granted_by uuid references auth.users(id), created_at timestamptz not null default now(), primary key(user_id,role));
create table public.organizations (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, country_code char(2), official_url text, verified_at timestamptz);
create table public.subjects (id uuid primary key default gen_random_uuid(), parent_id uuid references public.subjects(id), name text not null, slug text unique not null);
create table public.exams (id uuid primary key default gen_random_uuid(), organization_id uuid references public.organizations(id), subject_id uuid references public.subjects(id), name text not null, slug text unique not null, country_code char(2), level text, age_group text, qualification_stage text, team_event boolean not null default false, active boolean not null default true, official_url text, overview text, metadata jsonb not null default '{}', source_url text, last_verified_at timestamptz, featured boolean not null default false, created_at timestamptz not null default now());
create table public.exam_versions (id uuid primary key default gen_random_uuid(), exam_id uuid not null references public.exams(id) on delete cascade, label text not null, effective_from date, effective_to date, calculator_policy text, response_modes text[] not null default '{}', timing_minutes integer, scoring jsonb not null default '{}', source_url text, last_verified_at timestamptz, unique(exam_id,label));
create table public.exam_sections (id uuid primary key default gen_random_uuid(), exam_version_id uuid not null references public.exam_versions(id) on delete cascade, name text not null, position smallint not null, timing_minutes smallint, question_count smallint, break_after_minutes smallint, rules jsonb not null default '{}', unique(exam_version_id,position));
create table public.topics (id uuid primary key default gen_random_uuid(), subject_id uuid references public.subjects(id), parent_id uuid references public.topics(id), name text not null, slug text not null, unique(subject_id,slug));
create table public.skills (id uuid primary key default gen_random_uuid(), topic_id uuid references public.topics(id), name text not null, slug text not null, prerequisites uuid[] not null default '{}', unique(topic_id,slug));
create table public.answer_formats (id uuid primary key default gen_random_uuid(), code text unique not null, schema jsonb not null, validation_rules jsonb not null default '{}');
create table public.licenses (id uuid primary key default gen_random_uuid(), code text unique not null, name text not null, copyright_owner text not null, commercial_use boolean not null default false, ai_training boolean not null default false, attribution_required boolean not null default true, terms_url text, verified_by uuid references auth.users(id), verified_at timestamptz);

create table public.questions (id uuid primary key default gen_random_uuid(), stable_id text unique not null, exam_id uuid not null references public.exams(id), current_version_id uuid, status content_status not null default 'draft', type question_type not null, difficulty smallint check(difficulty between 1 and 5), estimated_seconds integer check(estimated_seconds>0), quality_score numeric(3,2) check(quality_score between 0 and 10), similarity_hash text, embedding vector(1536), batch_tag text, published_at timestamptz, retired_at timestamptz, created_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.question_versions (id uuid primary key default gen_random_uuid(), question_id uuid not null references public.questions(id) on delete cascade, version integer not null, exam_version_id uuid references public.exam_versions(id), section_id uuid references public.exam_sections(id), answer_format_id uuid references public.answer_formats(id), prompt jsonb not null, answer jsonb not null, common_mistakes jsonb not null default '[]', prerequisites jsonb not null default '[]', change_summary text, created_by uuid references auth.users(id), created_at timestamptz not null default now(), unique(question_id,version));
alter table public.questions add constraint questions_current_version_fk foreign key(current_version_id) references public.question_versions(id);
create table public.question_choices (id uuid primary key default gen_random_uuid(), question_version_id uuid not null references public.question_versions(id) on delete cascade, position smallint not null, content jsonb not null, is_correct boolean not null default false, rationale text, unique(question_version_id,position));
create table public.question_assets (id uuid primary key default gen_random_uuid(), question_version_id uuid not null references public.question_versions(id) on delete cascade, storage_path text not null, kind text not null, alt_text text, checksum text not null, validated_at timestamptz);
create table public.question_topics (question_id uuid references public.questions(id) on delete cascade, topic_id uuid references public.topics(id), weight numeric(3,2) default 1, primary key(question_id,topic_id));
create table public.question_skills (question_id uuid references public.questions(id) on delete cascade, skill_id uuid references public.skills(id), weight numeric(3,2) default 1, primary key(question_id,skill_id));
create table public.question_sources (id uuid primary key default gen_random_uuid(), question_version_id uuid not null references public.question_versions(id) on delete cascade, source_type text not null check(source_type in ('original','licensed_official','public_domain','open_license')), organization_id uuid references public.organizations(id), original_url text, archive_url text, license_id uuid not null references public.licenses(id), attribution text, checked_at timestamptz not null default now());
create table public.solutions (id uuid primary key default gen_random_uuid(), question_version_id uuid not null references public.question_versions(id) on delete cascade, kind text not null check(kind in ('concise','step_by_step','rigorous','faster_method')), content jsonb not null, verified boolean not null default false);
create table public.hints (id uuid primary key default gen_random_uuid(), question_version_id uuid not null references public.question_versions(id) on delete cascade, position smallint not null, content jsonb not null, unique(question_version_id,position));
create table public.rubrics (id uuid primary key default gen_random_uuid(), question_version_id uuid not null references public.question_versions(id) on delete cascade, total_points numeric(5,2) not null, criteria jsonb not null);
create table public.content_reviews (id uuid primary key default gen_random_uuid(), question_version_id uuid not null references public.question_versions(id) on delete cascade, reviewer_id uuid not null references auth.users(id), stage text not null, decision review_decision not null default 'pending', notes text, validation_results jsonb not null default '{}', created_at timestamptz not null default now(), decided_at timestamptz);

create table public.practice_sessions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, exam_id uuid references public.exams(id), exam_version_id uuid references public.exam_versions(id), mode text not null, state text not null default 'active', settings jsonb not null default '{}', started_at timestamptz not null default now(), submitted_at timestamptz);
create table public.practice_attempts (id uuid primary key default gen_random_uuid(), session_id uuid not null references public.practice_sessions(id) on delete cascade, question_id uuid not null references public.questions(id), question_version_id uuid not null references public.question_versions(id), response jsonb, correct boolean, confidence smallint check(confidence between 1 and 3), guessed boolean not null default false, hints_used smallint not null default 0, response_ms integer, flagged boolean not null default false, answered_at timestamptz);
create table public.user_question_history (user_id uuid references auth.users(id) on delete cascade, question_id uuid references public.questions(id), attempts integer not null default 0, correct_attempts integer not null default 0, last_seen_at timestamptz, next_review_at timestamptz, last_outcome jsonb, primary key(user_id,question_id));
create table public.mastery_records (user_id uuid references auth.users(id) on delete cascade, exam_id uuid references public.exams(id), topic_id uuid references public.topics(id), skill_id uuid references public.skills(id), state text not null check(state in ('not_started','learning','developing','proficient','mastered','needs_review')), evidence jsonb not null default '{}', review_due_at timestamptz, updated_at timestamptz not null default now(), id uuid primary key default gen_random_uuid());
create table public.study_plans (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, exam_id uuid references public.exams(id), target_date date, target_outcome text, weekly_minutes integer, settings jsonb not null default '{}', active boolean not null default true, created_at timestamptz not null default now());
create table public.study_plan_tasks (id uuid primary key default gen_random_uuid(), plan_id uuid not null references public.study_plans(id) on delete cascade, due_date date not null, position numeric not null, kind text not null, payload jsonb not null, completed_at timestamptz);
create table public.alarms (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, local_time time not null, timezone text not null, days smallint[] not null, enabled boolean not null default true, question_count smallint not null default 10 check(question_count between 1 and 50), settings jsonb not null default '{}', created_at timestamptz not null default now());
create table public.alarm_sessions (id uuid primary key default gen_random_uuid(), alarm_id uuid not null references public.alarms(id) on delete cascade, scheduled_for timestamptz not null, started_at timestamptz, completed_at timestamptz, dismissed_at timestamptz, dismiss_reason text, required_correct smallint not null, completed_correct smallint not null default 0);
create table public.alarm_question_attempts (alarm_session_id uuid references public.alarm_sessions(id) on delete cascade, practice_attempt_id uuid references public.practice_attempts(id) on delete cascade, primary key(alarm_session_id,practice_attempt_id));
create table public.bookmarks (user_id uuid references auth.users(id) on delete cascade, question_id uuid references public.questions(id), note text, created_at timestamptz not null default now(), primary key(user_id,question_id));
create table public.reports (id uuid primary key default gen_random_uuid(), reporter_id uuid references auth.users(id), question_id uuid references public.questions(id), reason text not null, detail text, status text not null default 'open', created_at timestamptz not null default now());
create table public.generation_jobs (id uuid primary key default gen_random_uuid(), created_by uuid references auth.users(id), specification jsonb not null, model text, status text not null default 'queued', output_batch text, error text, created_at timestamptz not null default now());
create table public.import_jobs (id uuid primary key default gen_random_uuid(), created_by uuid references auth.users(id), filename text not null, checksum text not null, status text not null default 'queued', received_count integer not null default 0, accepted_count integer not null default 0, rejected_count integer not null default 0, report jsonb not null default '{}', rollback_data jsonb, created_at timestamptz not null default now());
create table public.audit_logs (id bigint generated always as identity primary key, actor_id uuid references auth.users(id), action text not null, entity_type text not null, entity_id text not null, metadata jsonb not null default '{}', ip_hash text, created_at timestamptz not null default now());

create index questions_public_exam_idx on public.questions(exam_id,difficulty,published_at desc) where status='published';
create index questions_similarity_idx on public.questions(similarity_hash) where similarity_hash is not null;
create index question_versions_prompt_fts_idx on public.question_versions using gin(to_tsvector('english',coalesce(prompt->>'text','')));
create index question_embedding_idx on public.questions using hnsw(embedding vector_cosine_ops);
create index attempts_session_idx on public.practice_attempts(session_id,answered_at);
create index history_review_idx on public.user_question_history(user_id,next_review_at);
create index mastery_user_idx on public.mastery_records(user_id,exam_id,state);
create index review_queue_idx on public.content_reviews(stage,decision,created_at);
create index audit_entity_idx on public.audit_logs(entity_type,entity_id,created_at desc);

alter table public.profiles enable row level security; alter table public.user_roles enable row level security; alter table public.practice_sessions enable row level security; alter table public.practice_attempts enable row level security; alter table public.user_question_history enable row level security; alter table public.mastery_records enable row level security; alter table public.study_plans enable row level security; alter table public.study_plan_tasks enable row level security; alter table public.alarms enable row level security; alter table public.alarm_sessions enable row level security; alter table public.bookmarks enable row level security; alter table public.questions enable row level security; alter table public.question_versions enable row level security;
create policy "profiles self" on public.profiles for all using(id=auth.uid()) with check(id=auth.uid());
create policy "roles visible to self" on public.user_roles for select using(user_id=auth.uid());
create policy "sessions owned" on public.practice_sessions for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "attempts through owned session" on public.practice_attempts for all using(exists(select 1 from public.practice_sessions s where s.id=session_id and s.user_id=auth.uid())) with check(exists(select 1 from public.practice_sessions s where s.id=session_id and s.user_id=auth.uid()));
create policy "history owned" on public.user_question_history for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "mastery owned" on public.mastery_records for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "plans owned" on public.study_plans for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "tasks through owned plan" on public.study_plan_tasks for all using(exists(select 1 from public.study_plans p where p.id=plan_id and p.user_id=auth.uid())) with check(exists(select 1 from public.study_plans p where p.id=plan_id and p.user_id=auth.uid()));
create policy "alarms owned" on public.alarms for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "alarm sessions owned" on public.alarm_sessions for select using(exists(select 1 from public.alarms a where a.id=alarm_id and a.user_id=auth.uid()));
create policy "bookmarks owned" on public.bookmarks for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "published questions only" on public.questions for select using(status='published');
create policy "published versions only" on public.question_versions for select using(exists(select 1 from public.questions q where q.id=question_id and q.status='published' and q.current_version_id=question_versions.id));

create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id) values(new.id); insert into public.user_roles(user_id,role) values(new.id,'student'); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
